create trigger "activity_updated_at_update" after update on "activity" for each row when new."updatedAt" is old."updatedAt" begin
  update "activity" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "activity"."id" = new."id";
end;
create trigger "album_updated_at_update" after update on "album" for each row when new."updatedAt" is old."updatedAt" begin
  update "album" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "album"."id" = new."id";
end;
create trigger "album_asset_album_asset_delete_audit_delete" after delete on "album_asset" for each row when audit_hop('album_asset') <= 1 begin
  insert into album_asset_audit ("albumId", "assetId")
     select * from (select old."albumId", old."assetId")
     where exists (select 1 from "album" where "album"."id" = old."albumId");
end;
create trigger "album_asset_updated_at_update" after update on "album_asset" for each row when new."updatedAt" is old."updatedAt" begin
  update "album_asset" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "album_asset"."albumId" = new."albumId" and "album_asset"."assetId" = new."assetId";
end;
create trigger "album_user_album_user_delete_delete" after delete on "album_user" for each row begin
  delete from "album" where "album"."id" = old."albumId" and not exists (select "albumId" from "album_user" where "album_user"."albumId" = "album"."id" and "album_user"."role" = 'owner');
end;
create trigger "album_user_album_user_delete_audit_delete" after delete on "album_user" for each row when audit_hop('album_user') <= 1 begin
  insert into album_audit ("albumId", "userId") values (old."albumId", old."userId");
  insert into album_user_audit ("albumId", "userId")
     select * from (select old."albumId", old."userId")
     where exists (select 1 from "album" where "album"."id" = old."albumId");
end;
create trigger "album_user_album_user_after_insert_insert" after insert on "album_user" for each row begin
  update "album" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "id" = new."albumId" and new."role" <> 'owner';
end;
create trigger "album_user_updated_at_update" after update on "album_user" for each row when new."updatedAt" is old."updatedAt" begin
  update "album_user" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "album_user"."albumId" = new."albumId" and "album_user"."userId" = new."userId";
end;
create trigger "api_key_updated_at_update" after update on "api_key" for each row when new."updatedAt" is old."updatedAt" begin
  update "api_key" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "api_key"."id" = new."id";
end;
create trigger "asset_asset_face_update_asset_state_update" after update on "asset" for each row when old."ownerId" is not new."ownerId" or old."visibility" is not new."visibility" or old."deletedAt" is not new."deletedAt" begin
  update "asset_face" set "ownerId" = new."ownerId", "assetVisibility" = new."visibility", "assetDeletedAt" = new."deletedAt" where "assetId" = new."id";
end;
create trigger "asset_asset_delete_audit_delete" after delete on "asset" for each row when audit_hop('asset') = 0 begin
  insert into asset_audit ("assetId", "ownerId") values (old."id", old."ownerId");
end;
create trigger "asset_updated_at_update" after update on "asset" for each row when new."updatedAt" is old."updatedAt" begin
  update "asset" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "asset"."id" = new."id";
end;
create trigger "asset_edit_asset_edit_audit_delete" after delete on "asset_edit" for each row when audit_hop('asset_edit') = 0 begin
  insert into asset_edit_audit ("editId", "assetId") values (old."id", old."assetId");
end;
create trigger "asset_edit_asset_edit_delete_delete" after delete on "asset_edit" for each row when audit_hop('asset_edit') = 0 begin
  update "asset" set "isEdited" = 0 where "id" = old."assetId" and "isEdited" = 1 and not exists (select 1 from "asset_edit" edit where edit."assetId" = "asset"."id");
end;
create trigger "asset_edit_asset_edit_insert_insert" after insert on "asset_edit" for each row begin
  update "asset" set "isEdited" = 1 where "id" = new."assetId" and "isEdited" = 0;
end;
create trigger "asset_edit_updated_at_update" after update on "asset_edit" for each row when new."updatedAt" is old."updatedAt" begin
  update "asset_edit" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "asset_edit"."id" = new."id";
end;
create trigger "asset_exif_updated_at_update" after update on "asset_exif" for each row when new."updatedAt" is old."updatedAt" begin
  update "asset_exif" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "asset_exif"."assetId" = new."assetId";
end;
create trigger "asset_face_asset_face_audit_delete" after delete on "asset_face" for each row when audit_hop('asset_face') = 0 begin
  insert into asset_face_audit ("assetFaceId", "assetId") values (old."id", old."assetId");
end;
