  update "person_user" set "updatedAt" = clock_timestamp(), "updateId" = uuidv7() where "person_user"."personGroupId" = new."personGroupId" and "person_user"."sharedById" = new."sharedById" and "person_user"."sharedWithId" = new."sharedWithId";
